+    private FileSyncedProperties getOrCreateStoredRules(File file) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(file.getCanonicalPath(), path -> new FileSyncedProperties(file));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
