+    private void maintainIntegrity() {
+        if (integrityMode == IntegrityMode.IGNORE) {
+            return;
+        }
+
+        IntegrityAnalysis analysis = analyzeIntegrity();
+        if (integrityMode == IntegrityMode.FAIL) {
+            if (analysis.hasProblems()) {
+                throw new StoreInitializationFailedException(analysis.report());
+            }
+            return;
+        }
+
+        repair(analysis);
+    }
+
+    private IntegrityAnalysis analyzeIntegrity() {
+        List<RuleEntry> entries = storedRules.entries();
+        Collections.sort(entries, Comparator.comparing(entry -> entry.description));
+
+        Map<String, List<RuleEntry>> recordedNames = groupByRecordedName(entries);
+        Map<String, List<RuleEntry>> resolvedFiles = new HashMap<>();
+        Map<String, List<RuleEntry>> derivedNames = new HashMap<>();
+
+        for (RuleEntry entry : entries) {
+            entry.recordedFile = inspectRecordedFile(entry.recordedName);
+            String resolvedIdentity = entry.recordedFile.resolvedIdentity;
+            if (resolvedIdentity != null) {
+                resolvedFiles.computeIfAbsent(resolvedIdentity, ignored -> new ArrayList<>()).add(entry);
+            }
+
+            entry.derivedName = createRuleFileName(entry.description);
+            entry.derivedFile = inspectDerivedFile(entry.derivedName);
+            derivedNames.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+
+            entry.broken = !entry.recordedFile.valid;
+            entry.resolved = entry.recordedFile.valid && hasNoViolations(entry.recordedName);
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+        }
+
+        Set<RuleEntry> sharedEntries = new HashSet<>();
+        addGroupsTo(sharedEntries, recordedNames);
+        addGroupsTo(sharedEntries, resolvedFiles);
+        for (RuleEntry entry : entries) {
+            entry.shared = sharedEntries.contains(entry);
+            List<RuleEntry> sameDerivedName = derivedNames.get(entry.derivedName);
+            entry.colliding = sameDerivedName != null && sameDerivedName.size() > 1;
+            entry.occupied = isOccupied(entry, entries);
+        }
+
+        return new IntegrityAnalysis(entries, findUnownedFiles(entries));
+    }
+
+    private Map<String, List<RuleEntry>> groupByRecordedName(List<RuleEntry> entries) {
+        Map<String, List<RuleEntry>> result = new HashMap<>();
+        for (RuleEntry entry : entries) {
+            result.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+        }
+        return result;
+    }
+
+    private void addGroupsTo(Set<RuleEntry> destination, Map<String, List<RuleEntry>> groups) {
+        for (List<RuleEntry> group : groups.values()) {
+            if (group.size() > 1) {
+                destination.addAll(group);
+            }
+        }
+    }
+
+    private boolean isOccupied(RuleEntry entry, List<RuleEntry> entries) {
+        if (entry.derivedName.equals(entry.recordedName)) {
+            return !entry.derivedFile.directlyInFolder;
+        }
+        if (!entry.derivedFile.directlyInFolder || STORED_RULES_FILE_NAME.equals(entry.derivedName)) {
+            return true;
+        }
+        if (entry.derivedFile.exists) {
+            return true;
+        }
+        for (RuleEntry other : entries) {
+            if (other != entry && entry.derivedName.equals(other.recordedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private List<String> findUnownedFiles(List<RuleEntry> entries) {
+        Set<String> recordedNames = new HashSet<>();
+        for (RuleEntry entry : entries) {
+            recordedNames.add(entry.recordedName);
+        }
+
+        List<String> result = new ArrayList<>();
+        File[] files = storeFolder.listFiles();
+        if (files == null) {
+            return result;
+        }
+        for (File file : files) {
+            if (STORED_RULES_FILE_NAME.equals(file.getName()) || recordedNames.contains(file.getName())) {
+                continue;
+            }
+            if (Files.isRegularFile(file.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                result.add(file.getName());
+            }
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private void repair(IntegrityAnalysis analysis) {
+        boolean indexChanged = false;
+        for (RuleEntry entry : analysis.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken || entry.resolved) {
+                if (entry.resolved) {
+                    deleteRecordedFile(entry);
+                }
+                storedRules.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveRecordedFile(entry);
+                storedRules.replace(entry.description, entry.derivedName);
+                indexChanged = true;
+            }
+        }
+        if (indexChanged) {
+            storedRules.syncFileSystem();
+        }
+    }
+
+    private void deleteRecordedFile(RuleEntry entry) {
+        if (!entry.recordedFile.valid || entry.recordedFile.resolvedFile == null
+                || entry.recordedFile.resolvedFile.equals(storedRulesFile.getCanonicalFile())) {
+            return;
+        }
+        try {
+            File recordedPath = new File(storeFolder, entry.recordedName);
+            File resolvedFile = entry.recordedFile.resolvedFile;
+            if (!recordedPath.getCanonicalFile().equals(recordedPath.getAbsoluteFile())) {
+                // The comparison above is only a cheap indication of a link. The canonical file
+                // is always removed first, and the recorded directory entry is then removed too.
+                Files.deleteIfExists(resolvedFile.toPath());
+                if (!resolvedFile.equals(recordedPath.getCanonicalFile())) {
+                    Files.deleteIfExists(recordedPath.toPath());
+                }
+            } else {
+                Files.deleteIfExists(recordedPath.toPath());
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void moveRecordedFile(RuleEntry entry) {
+        try {
+            File recordedPath = new File(storeFolder, entry.recordedName);
+            File source = entry.recordedFile.resolvedFile;
+            File target = entry.derivedFile.resolvedFile;
+            Files.move(source.toPath(), target.toPath());
+            if (!source.equals(recordedPath.getCanonicalFile())) {
+                Files.deleteIfExists(recordedPath.toPath());
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean hasNoViolations(String fileName) {
+        try {
+            return readLines(fileName).isEmpty();
+        } catch (RuntimeException e) {
+            return false;
+        }
+    }
+
+    private RuleViolationFileNameStrategy strategyForName() {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalStateException("The store has not been initialized");
+        }
+        return ruleViolationFileNameStrategy;
+    }
+
+    private String createRuleFileName(String description) {
+        String result = strategyForName().createRuleFileName(description);
+        if (result == null || result.trim().isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
+
+    private FileInspection inspectRecordedFile(String name) {
+        try {
+            File path = new File(storeFolder, name);
+            boolean exists = Files.exists(path.toPath(), LinkOption.NOFOLLOW_LINKS);
+            if (!exists || !Files.exists(path.toPath())) {
+                return FileInspection.broken(exists ? path.getCanonicalFile() : null);
+            }
+            File resolved = path.getCanonicalFile();
+            boolean directRegular = Files.isRegularFile(resolved.toPath(), LinkOption.NOFOLLOW_LINKS)
+                    && isRegularFileDirectlyInFolder(resolved)
+                    && !resolved.equals(storedRulesFile.getCanonicalFile());
+            return directRegular
+                    ? FileInspection.valid(resolved)
+                    : FileInspection.broken(resolved);
+        } catch (IOException | RuntimeException e) {
+            return FileInspection.broken(null);
+        }
+    }
+
+    private FileInspection inspectDerivedFile(String name) {
+        try {
+            File path = new File(storeFolder, name);
+            boolean exists = Files.exists(path.toPath(), LinkOption.NOFOLLOW_LINKS);
+            File resolved = path.getCanonicalFile();
+            boolean direct = isRegularFileDirectlyInFolder(resolved)
+                    && !resolved.equals(storedRulesFile.getCanonicalFile());
+            return new FileInspection(direct, exists, resolved, direct ? resolved.getCanonicalPath() : null);
+        } catch (IOException | RuntimeException e) {
+            return new FileInspection(false, false, null, null);
+        }
+    }
+
+    private boolean isRegularFileDirectlyInFolder(File file) {
+        try {
+            File canonical = file.getCanonicalFile();
+            return Files.isRegularFile(canonical.toPath(), LinkOption.NOFOLLOW_LINKS)
+                    && canonical.getParentFile().equals(canonicalStoreFolder);
+        } catch (IOException | RuntimeException e) {
+            return false;
+        }
+    }
+
+    private void deleteIndexAfterFailedInitialization() {
+        try {
+            Files.deleteIfExists(storedRulesFile.toPath());
+            storedRules.clear();
+        } catch (IOException e) {
+            log.debug("Could not remove the index created by a rejected initialization", e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        return storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (integrityMode == IntegrityMode.REPAIR && violations.isEmpty()) {
+                if (existingFileName != null) {
+                    forgetKnownRule(description, existingFileName);
+                }
+                return;
+            }
+
+            String fileName = existingFileName != null ? existingFileName : createRuleFileName(description);
+            ensureWritableTarget(description, fileName, existingFileName != null);
+            write(violations, new File(storeFolder, fileName), existingFileName != null);
+            if (existingFileName == null) {
+                storedRules.putIfAbsentWithoutSync(description, fileName);
+                storedRules.syncFileSystem();
+            }
+        }
+    }
+
+    private void forgetKnownRule(String description, String fileName) {
+        if (!isSharedWithAnotherEntry(description, fileName)) {
+            RuleEntry entry = new RuleEntry(description, fileName);
+            entry.recordedFile = inspectRecordedFile(fileName);
+            if (entry.recordedFile.valid) {
+                deleteRecordedFile(entry);
+            }
+        }
+        storedRules.remove(description);
+        storedRules.syncFileSystem();
+    }
+
+    private boolean isSharedWithAnotherEntry(String description, String fileName) {
+        FileInspection own = inspectRecordedFile(fileName);
+        for (RuleEntry other : storedRules.entries()) {
+            if (description.equals(other.description)) {
+                continue;
+            }
+            if (fileName.equals(other.recordedName)) {
+                return true;
+            }
+            if (own.resolvedIdentity != null) {
+                FileInspection otherFile = inspectRecordedFile(other.recordedName);
+                if (own.resolvedIdentity.equals(otherFile.resolvedIdentity)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
+
+    private void ensureWritableTarget(String description, String fileName, boolean existingEntry) {
+        try {
+            File target = new File(storeFolder, fileName);
+            File canonicalTarget = target.getCanonicalFile();
+            if (!canonicalTarget.getParentFile().equals(canonicalStoreFolder)
+                    || canonicalTarget.equals(storedRulesFile.getCanonicalFile())
+                    || STORED_RULES_FILE_NAME.equals(fileName)) {
+                throw unsafeSave(description, fileName);
+            }
+            if (!existingEntry) {
+                if (storedRules.isFileNameRecordedByAnotherEntry(fileName)
+                        || Files.exists(target.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                    throw unsafeSave(description, fileName);
