    private void write(List<String> violations, File ruleDetails, boolean existingEntry) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        try {
            if (existingEntry) {
                Files.write(ruleDetails.toPath(), builder.toString().getBytes(UTF_8));
            } else {
                Files.write(ruleDetails.toPath(), builder.toString().getBytes(UTF_8), StandardOpenOption.CREATE_NEW);
            }
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n").replace("\r", "\\\r");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n").replace("\\\r", "\r");
    }

    @Override
    public List<String> getViolations(ArchRule rule) {
        String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
        List<String> result = readLines(ruleDetailsFileName);
        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
        return result;
    }

    private List<String> readLines(String ruleDetailsFileName) {
        String violationsText = readStoreFile(ruleDetailsFileName);
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
                .map(this::unescape)
                .collect(toList());
    }

    private String readStoreFile(String fileName) {
        try {
            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
            return normalizeLineBreaks(result);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private String normalizeLineBreaks(String value) {
        return value.replace("\r\n", "\n").replace('\r', '\n');
    }

    private String createRuleFileNameFromDescription(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String lastWord = null;
        while (matcher.find()) {
            lastWord = matcher.group();
        }
        if (lastWord == null) {
            lastWord = "rule";
        }
        String digest;
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256").digest(description.getBytes(UTF_8));
            StringBuilder result = new StringBuilder();
            for (byte value : hash) {
                result.append(String.format("%02x", value & 0xff));
            }
            digest = result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new StoreInitializationFailedException(e);
        }
        if (lastWord.length() > 100) {
            lastWord = lastWord.substring(lastWord.length() - 100);
        }
        return "rule-" + lastWord + "-" + digest;
    }

    private static class FileSyncedProperties {
        private final File propertiesFile;
        private Properties loadedProperties;
        private boolean createdDuringInitialization;

        FileSyncedProperties(File file) {
            propertiesFile = file;
        }

        synchronized boolean initialize(boolean allowCreation) {
            try {
                createdDuringInitialization = false;
                File directory = propertiesFile.getParentFile();
                if (!directory.exists() && !allowCreation) {
                    return false;
                }
                if (!directory.exists() && !directory.mkdirs() && !directory.isDirectory()) {
                    return false;
                }
                if (!directory.isDirectory()) {
                    return false;
                }
                if (!Files.exists(propertiesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                    if (!allowCreation) {
                        return false;
                    }
                    if (propertiesFile.createNewFile()) {
                        createdDuringInitialization = true;
                    } else if (!Files.exists(propertiesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                        return false;
                    }
                }
                loadedProperties = loadRulesFrom(propertiesFile);
                return true;
            } catch (IOException e) {
                return false;
            }
        }

        synchronized boolean createdDuringInitialization() {
            return createdDuringInitialization;
        }

        private Properties loadRulesFrom(File file) {
            Properties result = new Properties();
            try (FileInputStream inputStream = new FileInputStream(file)) {
                result.load(inputStream);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
            return result;
        }

        synchronized boolean containsKey(String propertyName) {
            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
        }

        synchronized String getProperty(String propertyName) {
            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
        }

        synchronized List<RuleEntry> entries() {
            List<RuleEntry> result = new ArrayList<>();
            for (String name : loadedProperties.stringPropertyNames()) {
                result.add(new RuleEntry(name, loadedProperties.getProperty(name)));
            }
            return result;
        }

        synchronized boolean isFileNameRecordedByAnotherEntry(String fileName) {
            for (String value : loadedProperties.stringPropertyNames()) {
                if (fileName.equals(loadedProperties.getProperty(value))) {
                    return true;
                }
            }
            return false;
        }

        synchronized void putIfAbsentWithoutSync(String key, String value) {
            String normalizedKey = ensureUnixLineBreaks(key);
            if (!loadedProperties.containsKey(normalizedKey)) {
                loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
            }
        }

        synchronized void remove(String key) {
            loadedProperties.remove(ensureUnixLineBreaks(key));
        }

        synchronized void replace(String key, String value) {
            loadedProperties.setProperty(ensureUnixLineBreaks(key), ensureUnixLineBreaks(value));
        }

        synchronized void syncFileSystem() {
            try (FileOutputStream outputStream = new FileOutputStream(propertiesFile)) {
                loadedProperties.store(outputStream, "");
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }

        synchronized void clear() {
            loadedProperties = new Properties();
        }
    }

